from _lib import File
F=File('pre2020_ktm2t','o-k2t','KTM 125 SX, 150 SX and 250 SX two-strokes 2012-2018 by generation: what changed, dyno and weight, jetting, power-valve settings, tester suspension settings, gearing, known problems and fixes (knowledge push 2026-11)','KTM',['125 SX','150 SX','250 SX'],list(range(2011,2020)))
R=F.R; M='magazine'

# ============ 250 SX
s=F.src(M,"Motocross Action - 2012 KTM 250SX test","https://motocrossactionmag.com/mxas-2012-ktm-250sx-two-stroke-motocross-test-this-is-the-king-of-all-smokers","2011")
G=[2012,2013,2014,2015,2016]
R('identity','2012 250 SX changes',['250 SX'],G,"For 2012 the 250 SX got the rising-rate linkage and a new frame in place of PDS, the swingarm from the four-strokes, a VForce3 reed block, a new airbox and boot, new fork seals and bodywork shared with the four-strokes. The engine and this chassis ran through 2016; the 2017 was all new.",{'rear':'linkage from 2012'},'OEM',s)
R('power_feel','2012-2016 250 SX power and weight',['250 SX'],G,"The 2012-2016 250 SX makes about 50 hp on a magazine dyno, about 5 hp more than the YZ250 of the same years, and weighs 217-218 lb. It has little torque right off the bottom and snaps hard just before the midrange.",{'peak_hp':'about 50','weight_lb':'217-218'},'MEASURED',s)
R('setups','2012-2013 250 SX tester settings',['250 SX'],[2012,2013],"A magazine test crew's 2012 250 SX setup: fork 0.48 kg/mm springs (stock 0.44), 375 cc oil (stock 390), compression 7 clicks out (stock 12), rebound 12 out, legs 5 mm up (flush in sand). Shock 5.4 kg/mm spring (5.6 for faster or heavier riders), 105 mm sag, high-speed compression 2 turns out, low-speed 15 clicks out, rebound 12 out, with a link 1.25 mm longer than stock to stop the rear sitting high and dropping fast.",{'fork':'0.48 kg/mm (stock 0.44), 375 cc, comp 7 out (stock 12), reb 12 out, 5 mm up','shock':'5.4 kg/mm, sag 105 mm, HSC 2 turns, LSC 15 out, reb 12 out','link':'1.25 mm longer'},'TUNER',s)
R('setups','2012-2013 250 SX jetting',['250 SX'],[2012,2013],"The 2012 250 SX is lean as delivered. Testers went from the stock 158 main and N1EI needle to a 160 main and N1EH needle on the 3rd clip, with a 42 pilot and the air screw 1-1/2 turns out.",{'main':'160 (stock 158)','pilot':42,'needle':'N1EH (stock N1EI), 3rd clip','air_screw':'1-1/2 turns'},'TUNER',s)
R('engine_mods','2012-2016 250 SX power valve and maps',['250 SX'],G,"On the 2012-2016 250 SX one turn of the power-valve preload adjuster moves the opening point about 200 rpm within a 5,000-7,500 rpm window. KTM's accessory springs change how fast it opens: red quickest, yellow stock, green softest. There are two ignition maps: unplugging the single connector under the tank selects the soft one, which helps on hardpack.",{'preload':'1 turn = about 200 rpm','springs':'red quick / yellow stock / green soft'},'TUNER',s)
R('setups','250 SX gearing 2012-2016',['250 SX'],G,"Stock gearing on the 2012-2016 250 SX is 13/48; some riders add a tooth at the rear.",{'stock':'13/48'},'TUNER',s)
s2=F.src(M,"Motocross Action - 2014 KTM 250SX test","https://motocrossactionmag.com/mxas-2014-ktm-250sx-motocross-test-the-king-of-two-strokes-has-no-rivals-for-the-throne/","2013")
R('identity','2014 250 SX changes',['250 SX'],[2014],"2014 250 SX changes: carbon reed petals in a KTM twin-V block (they fit earlier four-bolt 250 SX reed blocks), a reshaped combustion chamber and squish with unchanged compression, more ignition advance, stronger inner clutch hubs, a 9 mm front master-cylinder piston (was 10), a lighter chain guide on stiffer mounts, new seat foam and a low-profile gas cap.",{},'OEM',s2)
R('setups','2014-2016 250 SX tester settings and jetting',['250 SX'],[2014,2015,2016],"A magazine test crew's 2014 250 SX setup: fork 0.46 kg/mm springs, oil at 370 cc for vets and 390 cc for pros (stock 380), compression 7 clicks out (stock 12), rebound 12 out, legs 5 mm up. Shock 5.4 kg/mm spring (5.7 for faster or heavier riders), 105 mm sag, high-speed compression 2 turns out, low-speed 15 clicks out, with a link 1.25 mm longer (lowers the rear 10 mm and firms the first part of the stroke). Jetting: 158 main (160 in cool weather), 40 pilot (stock 42), N1EH needle on the 4th clip (stock 3rd), air screw 1-1/2 turns.",{'fork':'0.46 kg/mm, 370-390 cc, comp 7 out (stock 12), reb 12 out, 5 mm up','shock':'5.4 kg/mm, sag 105 mm, HSC 2 turns, LSC 15 out','jetting':'158 main, 40 pilot, N1EH 4th clip, air screw 1-1/2'},'TUNER',s2,'medium','Tested on the 2014; the 2015-2016 250 SX kept this engine. The 2015-2016 fork is the WP 4CS, so the fork clicker numbers apply to the 2014 fork only.')
R('known_issues','2012-2016 250 SX weak points',['250 SX','125 SX','150 SX'],G,"Tester findings on the 2012-2016 KTM two-strokes: the nylon shock preload ring deforms (an aluminium ring or worm-drive adjuster needs the shock apart to fit), the stock rims are soft and the spokes by the rear rim lock loosen, sprocket bolts need checking, the seat foam breaks down early, the gas-cap vent hose knots when the cap is turned (route it through a hole in the steering-stem cap), and the stock bars are low for tall riders.",{},'TUNER',s2)

s=F.src(M,"Motocross Action - 2017 KTM 250SX race test","https://motocrossactionmag.com/mxa-race-test-2017-ktm-250sx-two-stroke","2016")
H=[2017,2018]
R('identity','2017 250 SX redesign',['250 SX'],H,"The 2017 250 SX was new: an overhauled engine on the same 66.4 x 72 mm bore and stroke (new cases, ports, head and clutch), a 38 mm Mikuni TMX carburettor in place of the Keihin, the lighter frame with 20% more torsional stiffness and a wheelbase 10 mm shorter, a shock 12 mm shorter and the WP AER 48 air fork. 211 lb without fuel; list price $7,699 (2018: $7,899, with the carburettor angle changed from 12 to 7 degrees and an orange frame).",{'bore_stroke_mm':'66.4 x 72','carb':'Mikuni TMX 38','weight_lb':211,'msrp_usd_2017':7699},'OEM',s)
s2=F.src(M,"Motocross Action - 2018 KTM 250SX race test","https://motocrossactionmag.com/mxa-race-test-2018-ktm-250sx-two-stroke","2017")
R('power_feel','2017-2018 250 SX dyno',['250 SX'],H,"On a magazine dyno the 2018 250 SX made 47.20 hp at 8,200 rpm, with 2 hp more than the YZ250 at 6,000 rpm, 4 more at 7,000 and 1.1 more at peak, and about 3 lb-ft more torque 500 rpm lower. Against the 2014-2016 engine it gained about 5 hp in the middle and lost about 1.5 at peak. The hit is abrupt and it signs off quickly after the peak, so it wants to be short-shifted. 212 lb.",{'peak_hp':47.2,'peak_rpm':8200,'weight_lb':212},'MEASURED',s2,'high')
R('setups','2017-2018 250 SX tester settings (AER)',['250 SX'],H,"A magazine test crew's 2017-2018 250 SX setup: fork air 144 psi (stock 147; below 144 it bottoms on big hits), compression 23 clicks out, rebound 19 out, legs at the second line. Shock stock 42 N/mm spring, 107 mm sag (stock 110; 102-108 works), high-speed compression 1-1/4 turns out (stock 2), low-speed 8 clicks out (stock 15), rebound 14 out (stock 15). Gearing 14/49 in place of 14/50.",{'fork_psi':'144 (stock 147)','fork':'comp 23 out, reb 19 out, second line','shock':'42 N/mm, sag 107 mm, HSC 1-1/4 turns (stock 2), LSC 8 out (stock 15), reb 14 out','gearing':'14/49 (stock 14/50)'},'TUNER',s2)
R('setups','2017-2018 250 SX jetting and premix',['250 SX'],H,"Jetting on the 2017-2018 250 SX (Mikuni TMX 38): stock 440 main, 42.5 pilot, 43-73 needle on the 3rd clip. On the 2017 testers ran a 450 main with the air screw 2-1/2 turns out; on the 2018 they stayed on the 440 main with a 45 pilot. The 2018 test crew mixed fuel at 60:1 (10.7 oz of oil to 5 gallons).",{'stock':'440 main, 42.5 pilot, 43-73 needle 3rd clip','2017_tested':'450 main, air screw 2-1/2 turns','2018_tested':'440 main, 45 pilot','premix':'60:1'},'TUNER',s2)
R('engine_mods','2017-2018 250 SX taming the hit',['250 SX'],H,"Ways testers softened the 2017-2018 250 SX: the power-valve adjuster (stock is one turn in from fully out; counter-clockwise is more aggressive, clockwise smoother; move it a quarter turn at a time, and 3/4 turn was one crew's sweet spot), a 49-tooth rear sprocket, tape over the airbox vent, and unplugging the map connector under the tank for the mellow ignition curve. An aftermarket hand dial replaces the adjuster screw for about $95.",{'power_valve_stock':'1 turn in from full out'},'TUNER',s2)

# ============ 125 SX
s=F.src(M,"Motocross Action - 2012 KTM 125SX test","https://motocrossactionmag.com/mxas-2012-ktm-125sx-motocross-test-an-old-friend-returns","2011")
G=[2012,2013,2014,2015]
R('identity','2012 125 SX changes',['125 SX','150 SX'],G,"For 2012 the 125 SX and 150 SX got the rising-rate linkage and a new frame in place of PDS (about 5 lb heavier), a new swingarm, head stay and air boot, a stronger kickstarter and new suspension settings. This chassis and engine ran 2012-2015; the 2016 bikes were all new.",{'rear':'linkage from 2012'},'OEM',s)
R('power_feel','2012-2015 125 SX dyno and weight',['125 SX'],G,"On a magazine dyno the 125 SX made 34.69 hp at 11,200 rpm in 2012 and 34.66 hp in 2014. It weighed 202 lb in 2012 and 206 lb in 2014. Good low-to-mid for a 125 with a softer top end than earlier KTM 125s; list price $6,499 in 2014.",{'peak_hp':34.69,'peak_rpm':11200,'weight_lb':'202-206','msrp_usd_2014':6499},'MEASURED',s,'high')
R('setups','2012-2013 125 SX tester settings and jetting',['125 SX'],[2012,2013],"A magazine test crew's 2012 125 SX setup: fork 0.42 kg/mm springs (0.44 or more for bigger or faster riders), 350 cc oil, compression 6 clicks out (stock 12), rebound 10 out (stock 12), legs 5 mm up. Shock 4.7 kg/mm spring, 100 mm sag, high-speed compression 2 turns out, low-speed 15 clicks out, rebound 15 out. Jetting (38 mm Keihin PWK): 182 main, 42 pilot, NOZI needle on the 3rd clip, air screw 1-1/2 turns. Stock gearing was kept.",{'fork':'0.42 kg/mm, 350 cc, comp 6 out (stock 12), reb 10 out, 5 mm up','shock':'4.7 kg/mm, sag 100 mm, HSC 2 turns, LSC 15 out, reb 15 out','jetting':'182 main, 42 pilot, NOZI 3rd clip, air screw 1-1/2'},'TUNER',s)
s2=F.src(M,"Motocross Action - 2014 KTM 125SX test","https://motocrossactionmag.com/ten-years-ago-today-mxas-2014-ktm-125sx-two-stroke-test","2013")
R('setups','2014-2015 125 SX tester settings and jetting',['125 SX'],[2014,2015],"A magazine test crew's 2014 125 SX setup: fork 0.44 kg/mm springs (stiffened from 0.42 for 2014), 350 cc oil (stock 360), compression 12 clicks out, rebound 12 out, legs 5 mm up. Shock 4.8 kg/mm spring (it suits about 150 lb; heavier riders need more), 100 mm sag, high-speed compression 2 turns out, low-speed 15 clicks out, rebound 15 out. Jetting: 185 main (stock 182), 40 pilot (stock 42), NOZH needle on the 4th clip, air screw 1-1/2 turns, on fresh 91-octane with some race fuel added. Stock gearing is 13/50 and too tall: one tooth more at the rear, two for tight tracks.",{'fork':'0.44 kg/mm, 350 cc, comp 12 out, reb 12 out, 5 mm up','shock':'4.8 kg/mm, sag 100 mm, HSC 2 turns, LSC 15 out, reb 15 out','jetting':'185 main, 40 pilot, NOZH 4th clip, air screw 1-1/2','gearing':'stock 13/50; 13/51 or 13/52'},'TUNER',s2,'medium','Tested on the 2014. The 2015 fork is the WP 4CS, so the fork clicker numbers apply to the 2014 fork only.')
s=F.src(M,"Motocross Action - 2017 KTM 125SX race test","https://motocrossactionmag.com/mxa-race-test-2017-ktm-125sx","2016")
H=[2016,2017,2018]
R('identity','2016-2018 125 SX',['125 SX'],H,"The 125 SX was built new from the ground up for 2016. For 2017 it got the WP AER 48 air fork (3.6 lb lighter than the 4CS), a stiffer upper clamp, a 38 mm Mikuni TMX carburettor in place of the Keihin PWK, a 39 N/mm shock spring, a longer brake pedal and milder rear pads. For 2018: an orange frame, aluminium head stays, revised fork and shock valving, and KTM changed the recommended premix from 60:1 to 40:1 with a richer pilot (25 to 35) and a 6BFY42-75 needle.",{'2016':'all new','2017':'AER fork, Mikuni TMX 38','2018':'40:1 premix, 35 pilot'},'OEM',s)
R('power_feel','2017-2018 125 SX dyno and weight',['125 SX'],[2017,2018],"On a magazine dyno the 2017-2018 125 SX made 37.27 hp and 17.35 lb-ft and weighed about 195 lb, over 4 lb less than the 2016. Lively off the bottom for a 125, smooth through the middle and it holds on top. List price $6,899 in 2017.",{'peak_hp':37.27,'peak_torque_lbft':17.35,'weight_lb':195,'msrp_usd_2017':6899},'MEASURED',s,'high')
R('setups','2017 125 SX tester settings and jetting',['125 SX'],[2017],"A magazine test crew's 2017 125 SX setup: fork air 123 psi for 155-170 lb riders and 125 psi for 170-200 lb, compression 22 clicks out (stock 12), rebound 11 out (stock 12), stock fork height. Shock 39 N/mm spring, 105 mm sag (stock 110), high-speed compression 2-1/2 turns out (stock 2), low-speed 8 clicks out (stock 15), rebound 15 out. Jetting (Mikuni TMX 38): 480 main, 25 pilot in place of the stock 45, 6BFY43-74 needle on the 3rd clip, air screw 1 turn. Power valve: stock is one turn in; two turns in gave the best mid-to-top for fast riders, 1-3/4 for vets and novices; beyond two turns the bottom suffers. Fork pressure can rise 4 psi in a moto, so check it every session.",{'fork_psi':'123 (155-170 lb), 125 (170-200 lb)','fork':'comp 22 out (stock 12), reb 11 out','shock':'39 N/mm, sag 105 mm, HSC 2-1/2 turns, LSC 8 out, reb 15 out','jetting':'480 main, 25 pilot (stock 45), 6BFY43-74 3rd clip, air screw 1 turn','power_valve':'2 turns in fast riders; 1-3/4 vets and novices'},'TUNER',s)
s2=F.src(M,"Motocross Action - 2018 KTM 125SX race test","https://motocrossactionmag.com/mxa-race-test-2018-ktm-125sx","2017")
R('setups','2018 125 SX tester settings and jetting',['125 SX'],[2018],"A magazine test crew's 2018 125 SX setup: fork air 127 psi (stock 124), compression 24 clicks out (stock 12), rebound 15 out (stock 12), legs at the first line. Shock 42 N/mm spring, 105 mm sag, high-speed compression 2 turns out, low-speed 15 clicks out, rebound 15 out. Jetting: 490 main (stock 480), 35 pilot, 6BFY42-75 needle on the 3rd clip, air screw 2 turns, at 40:1 premix. Start any carb tuning with the air screw. Stock 50-tooth rear; slower riders go to 51.",{'fork_psi':'127 (stock 124)','fork':'comp 24 out (stock 12), reb 15 out, first line','shock':'42 N/mm, sag 105 mm, HSC 2 turns, LSC 15 out, reb 15 out','jetting':'490 main (stock 480), 35 pilot, 6BFY42-75 3rd clip, air screw 2 turns','premix':'40:1','gearing':'stock 50T; 51T slower riders'},'TUNER',s2)
R('known_issues','2016-2018 125/150/250 SX weak points and fixes',['125 SX','150 SX','250 SX'],H,"Tester findings on the 2016-2018 KTM two-strokes: rear spokes loosen, especially by the rim lock, and sprocket bolts need checking before every ride; the fork air bleed screw strips (10 mm T-handle on the air side; the earlier Phillips screw fits the damping side); the power-valve adjuster has a square (Robertson) socket, and a flat screwdriver works; the plastic preload ring is weak; on 2017-2018 bikes the bar mounts twist in a crash (the 2016 lower mounts with the 2017 top mount cured it) and the Mikuni carburettor is fussier than the old Keihin; the 2017 rear pads grab when hot (2016 pads); tie-down hooks can crimp the front brake hose.",{},'TUNER',s2)

# ============ 150 SX
s=F.src(M,"Motocross Action - 2014 KTM 150SX test","https://motocrossactionmag.com/mxas-2014-ktm-150sx-motocross-test-this-bike-is-designed-to-be-ridden-by-a-special-kind-of-rider","2013")
R('identity','150 SX against the 125 SX, 2012-2015',['150 SX'],G,"The 2012-2015 150 SX is a 143.6 cc engine with a 56 x 58.4 mm bore and stroke (125 SX: 54 x 54.5 mm) and its own crank, cylinder, piston, power valve and pipe tuning. It has all-steel clutch plates with stiffer springs where the 125 uses aluminium, and 13/48 gearing against the 125's 13/50.",{'displacement_cc':143.6,'bore_stroke_mm':'56 x 58.4','gearing':'13/48'},'OEM',s)
R('power_feel','2012-2015 150 SX dyno and weight',['150 SX'],G,"On a magazine dyno the 2012-2014 150 SX made 38.81-38.83 hp at 11,100 rpm, about 4 hp more than the 125 SX. It weighed 205-206.5 lb. The powerband is narrow and it only makes speed when ridden hard. List price $6,599 in 2014.",{'peak_hp':38.81,'peak_rpm':11100,'weight_lb':'205-206.5','msrp_usd_2014':6599},'MEASURED',s,'high')
R('setups','2014-2015 150 SX tester settings and jetting',['150 SX'],[2014,2015],"A magazine test crew's 2014 150 SX setup: fork 0.44 kg/mm springs (stock 0.42), 350 cc oil (stock 360), compression 6 clicks out (stock 12), rebound 10 out (stock 12), legs 5 mm up. Shock 4.8 kg/mm spring (heavier for riders over about 150 lb), 100 mm sag, high-speed compression 2 turns out, low-speed 15 clicks out (stock 18), rebound 15 out. Jetting (38 mm Keihin PWK): 180 main, 40 pilot, N1EJ needle on the 3rd clip, air screw 1-1/2 turns. It runs lean: listen for pinging on poor fuel, in cold air or in deep sand, and add some race fuel. Gearing 13/49 in place of 13/48, or 13/50.",{'fork':'0.44 kg/mm (stock 0.42), 350 cc, comp 6 out (stock 12), reb 10 out, 5 mm up','shock':'4.8 kg/mm, sag 100 mm, HSC 2 turns, LSC 15 out, reb 15 out','jetting':'180 main, 40 pilot, N1EJ 3rd clip, air screw 1-1/2','gearing':'13/49 (stock 13/48)'},'TUNER',s,'medium','Tested on the 2014. The 2015 fork is the WP 4CS, so the fork clicker numbers apply to the 2014 fork only.')
s=F.src(M,"Motocross Action - 2016 KTM 150SX race test","https://motocrossactionmag.com/mxa-race-test-2016-ktm-150sx","2015")
R('identity','2016 150 SX redesign',['150 SX'],H,"The 2016 150 SX was all new: an engine 4 lb lighter with a 58 x 54.5 mm bore and stroke (143.99 cc; the 125 is 54 x 54.5), a six-speed gearbox and the 125's pipe, in the lighter frame with 20% more torsional stiffness and a wheelbase 10 mm shorter, a shock 12 mm shorter and softer 4.2 N/mm fork springs. It differs from the 125 SX in cylinder, piston, power valve, head stays, ignition map and jetting. 198 lb; list price $6,899. For 2017 it got the AER air fork and a Mikuni TMX carburettor.",{'displacement_cc':143.99,'bore_stroke_mm':'58 x 54.5','weight_lb_2016':198,'msrp_usd_2016':6899},'OEM',s)
R('power_feel','2016-2018 150 SX dyno and weight',['150 SX'],H,"On a magazine dyno the 2016 150 SX made 40.60 hp at 11,500 rpm and 18.63 lb-ft; the 2017 made the same and weighed 194 lb without fuel. The power is peaky and narrow: weak at part throttle and it falls off about 500 rpm past the peak.",{'peak_hp':40.6,'peak_rpm':11500,'peak_torque_lbft':18.63,'weight_lb_2017':194},'MEASURED',s,'high')
R('setups','2016 150 SX tester settings and jetting (4CS)',['150 SX'],[2016],"A magazine test crew's 2016 150 SX setup: fork 4.2 N/mm springs, compression 5 clicks out (stock 15), rebound 16 out (stock 15), legs 6 mm up. Shock 42 N/mm spring, 102 mm sag, high-speed compression 2 turns out, low-speed 6 clicks out (stock 15), rebound 9 out (stock 15). Jetting (Keihin PWK): 190 main, 52 pilot, NOZE needle on the 4th clip, air screw 3 turns out (stock 1). Gearing: 13/49 for less experienced riders, 14/49 for fast ones (stock 13/48).",{'fork':'4.2 N/mm, comp 5 out (stock 15), reb 16 out, 6 mm up','shock':'42 N/mm, sag 102 mm, HSC 2 turns, LSC 6 out (stock 15), reb 9 out (stock 15)','jetting':'190 main, 52 pilot, NOZE 4th clip, air screw 3 turns','gearing':'13/49 or 14/49 (stock 13/48)'},'TUNER',s)
s2=F.src(M,"Motocross Action - 2017 KTM 150SX race test","https://motocrossactionmag.com/mxa-race-test-2017-ktm-150sx","2016")
R('setups','2017-2018 150 SX tester settings and jetting (AER)',['150 SX'],[2017,2018],"A magazine test crew's 2017 150 SX setup: fork air 123 psi for 155-170 lb riders and 125 psi for 170-200 lb, compression 20 clicks out (stock 15), rebound 10 out (stock 15), legs at the third line; add pressure if it dives in corners, drop it if the front pushes on entry. Shock 42 N/mm spring, 105 mm sag (110 for stability on fast tracks), high-speed compression 2 turns out, low-speed 10 clicks out (stock 15), rebound 12 out (stock 15). Jetting (Mikuni TMX 38): 460 main (stock 470), 40 pilot (stock 45), 44-74 needle on the 1st clip (stock 43-74, 3rd), air screw 3 turns out (stock 1-1/2). Power valve: adjuster fully out, then in half a turn for a wider spread. Gearing: stock 13/48; 14/49 for pros, 14/50 for tight tracks.",{'fork_psi':'123 (155-170 lb), 125 (170-200 lb)','fork':'comp 20 out (stock 15), reb 10 out (stock 15), third line','shock':'42 N/mm, sag 105 mm, HSC 2 turns, LSC 10 out, reb 12 out','jetting':'460 main, 40 pilot, 44-74 1st clip, air screw 3 turns','gearing':'stock 13/48; 14/49 or 14/50'},'TUNER',s2,'medium','Tested on the 2017; the 2018 150 SX has the same engine and carburettor with revised fork and shock valving.')

if __name__=='__main__': F.write()
